import json, time, urllib.request, boto3
def handler(event, context):
    reason = None
    if event['RequestType'] == 'Create':
        try:
            reason = check(event['ResourceProperties'])
        except Exception as e:
            reason = 'cdkpf probe could not run: %r' % e
    body = {'Status': 'FAILED' if reason else 'SUCCESS', 'Reason': (reason or 'ok')[:900],
            'PhysicalResourceId': event.get('PhysicalResourceId', context.log_stream_name),
            'StackId': event['StackId'], 'RequestId': event['RequestId'], 'LogicalResourceId': event['LogicalResourceId']}
    urllib.request.urlopen(urllib.request.Request(event['ResponseURL'], data=json.dumps(body).encode(), method='PUT', headers={'Content-Type': ''}))
def check(p):
    # A new role takes a while to become assumable, so a failure is only reported
    # once it has persisted for about 100 seconds.
    gw = boto3.client('apigateway')
    deadline = time.time() + 100
    while True:
        r = gw.test_invoke_method(restApiId=p['RestApiId'], resourceId=p['ResourceId'], httpMethod=p['HttpMethod'])
        if r['status'] == 200:
            return None
        if time.time() > deadline:
            log = r.get('log', '')
            lines = [l for l in log.splitlines() if 'Execution failed' in l or 'Endpoint response' in l or 'rror' in l]
            return 'HTTP %s: %s' % (r['status'], ' | '.join(lines)[:700] or r.get('body', '')[:300])
        time.sleep(10)
